"use client";

import { useState } from "react";
import { useSubmit } from "@/lib/api";
import { TRANSACTION_TYPES, TRANSACTION_CATEGORIES } from "@/lib/types";
import { Select } from "@/components/finance/Select";
import { Input } from "@/components/finance/Input";
import { Button } from "@/components/finance/Button";

const TransactionForm = ({ onSaved }) => {
  const submit = useSubmit();
  const [formData, setFormData] = useState({
    account: "",
    date: new Date().toISOString().split('T')[0],
    description: "",
    amount: 0,
    type: TRANSACTION_TYPES.EXPENSE,
    category: "",
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    await submit("/api/finance/import/manual", {
      entity: "transaction",
      data: formData,
    });
    onSaved();
  };

  return (
    <form onSubmit={handleSubmit}>
      <Select
        name="account"
        label="Account"
        options={[]}
        value={formData.account}
        onChange={handleChange}
      />
      <Input
        name="date"
        label="Date"
        type="date"
        value={formData.date}
        onChange={handleChange}
      />
      <Input
        name="description"
        label="Description"
        value={formData.description}
        onChange={handleChange}
      />
      <Input
        name="amount"
        label="Amount"
        type="number"
        value={formData.amount}
        onChange={handleChange}
      />
      <Select
        name="type"
        label="Type"
        options={TRANSACTION_TYPES}
        value={formData.type}
        onChange={handleChange}
      />
      <Select
        name="category"
        label="Category"
        options={TRANSACTION_CATEGORIES}
        value={formData.category}
        onChange={handleChange}
      />
      <Button type="submit">Save</Button>
    </form>
  );
};

export default TransactionForm;
